using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Diagnostics;
namespace ExtremeLand {public sealed partial class Engine {
 public void ExtractSafe(string archive,string destination){if(!Path.GetFullPath(destination).StartsWith(Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Extracción fuera de la instalación.");using(var zip=ZipFile.OpenRead(archive)){long total=0;foreach(var e in zip.Entries){total+=e.Length;if(total>734003200L)throw new IOException("Componente demasiado grande.");string name=e.FullName.Replace('\\','/');if(name.StartsWith("/")||name.Contains(":")||name.Split('/').Any(p=>p==".."))throw new IOException("Ruta inválida en el componente.");string target=Path.GetFullPath(Path.Combine(destination,name));if(!target.StartsWith(Path.GetFullPath(destination).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Ruta inválida en el componente.");if(name.EndsWith("/")){Directory.CreateDirectory(target);continue;}Directory.CreateDirectory(Path.GetDirectoryName(target));e.ExtractToFile(target,true);}}}
 public async Task EnsureBackend(CancellationToken ct){if(File.Exists(Backend)&&File.Exists(Safe("backend/.verified-11.1.1")))return;Idle();var archive=await Download(PrismUrl,PrismHash,PrismSize,"Acceso de Minecraft",ct);string staging=Safe("backend-stage-"+Guid.NewGuid().ToString("N"));ExtractSafe(archive,staging);if(!File.Exists(Path.Combine(staging,"prismlauncher.exe")))throw new IOException("Falta el ejecutable del componente de acceso.");string dest=Safe("backend");if(Directory.Exists(dest))Directory.Move(dest,Safe("backend-old-"+Guid.NewGuid().ToString("N")));Directory.Move(staging,dest);File.WriteAllText(Safe("backend/.verified-11.1.1"),PrismHash);}
 public Process Start(bool account){if(!File.Exists(Backend))throw new IOException("Primero prepara el acceso de Minecraft.");return Process.Start(new ProcessStartInfo(Backend,"--dir "+Quote(PrismData)+(account?"":" --launch ExtremeLand")){WorkingDirectory=Path.GetDirectoryName(Backend),UseShellExecute=false});}
 public static string Quote(string v){if(v.Contains("\"")||v.Contains("\r")||v.Contains("\n"))throw new ArgumentException("Argumento inválido.");return "\""+v+"\"";}
}}
